const $=s=>document.querySelector(s),store=createStore({storageKey:'yoxi-city-life-polished-v1'}),ai=createAIGateway();
let caps={mode:'loading',tasks:[]},searchText='',filter='',searchResult=null,searchBusy=false,querySequence=0,importText='',importResult=null,planDraft=null,planResult=null,planError='',friendInput={mine:'攝影',friend:'看展'},friendParseError='',friendMine=['攝影'],friendWants=['看展'],friendPerson=null,friendSearched=false,createContext=null,myTab='saved',togetherTab='events',roomTimer;
const splitTerms=t=>String(t).split(/[、，,\s]+/).map(x=>x.trim()).filter(Boolean),dateLocal=d=>new Date(d-new Date(d).getTimezoneOffset()*60000).toISOString().slice(0,16);
function readInterests(text){
 const known=[...new Set(PLACES.filter(p=>!p.testData).flatMap(p=>p.tags))];
 const tags=[],unknown=[];
 for(const phrase of splitTerms(text)){
  const resolved=extractConstraints({query:phrase}),parsed=resolved.extracted.requiredActivities;
  if(parsed.length)tags.push(...parsed);
  else if(known.includes(phrase))tags.push(phrase);
  else unknown.push(phrase);
 }
 return {tags:[...new Set(tags)],unknown};
}
function startPlan(id,{query='',sourceKey='direct/'+id,interests=['攝影'],participants=[]}={}){
 if(planDraft?.placeId!==id||planDraft?.sourceKey!==sourceKey){planDraft={placeId:id,sourceKey,query,siteMinutes:60,budget:null,interests,participants};planResult=null;planError='';}
}
let memoryGallery=null,jointMount=null,jointState=null,jointDraft=null,jointError='',friendsMode='ai',guideMount=null,guideKey=null;const guideStates=new Map();
const route=()=>{const [name='explore',id='']=location.hash.slice(1).split('/');return {name:name||'explore',id:decodeURIComponent(id)}};
const go=p=>{if(location.hash==='#'+p){render();window.scrollTo(0,0)}else location.hash=p;};
const act=(type,p={})=>{const r=store.dispatch({type,...p});if(!r.ok)toast(r.error.message);return r};
const person=id=>id==='me'?store.getState().profile.displayName:TEST_PROFILES.find(p=>p.id===id)?.name||'成員';
const saved=id=>store.getState().activeProfileId==='me'&&store.getState().collections.some(c=>c.placeId===id);
const names={open:'開放加入',ready:'全員已確認',needs_host:'等待主揪接手',expired:'已截止',cancelled:'已取消',completed:'已完成',in_progress:'進行中'};
const invitationStatus=g=>g.remainingSeats===0&&['open','ready'].includes(g.status)?(g.status==='ready'?'名額已滿，已成團':'名額已滿，待成員確認'):(names[g.status]||g.status);
const costDisplay=(c,id)=>c.knownTotal===0&&c.unknownItems.some(x=>x!=='交通')?'待確認':money(c.perPerson[id]);
const fee=p=>p.fees.some(f=>!Number.isFinite(f.amount))?'費用待確認':p.fees.reduce((n,f)=>n+f.amount,0)===0?'免門票':money(p.fees.reduce((n,f)=>n+f.amount,0));
const back=(label,target='explore')=>`<button class="back" data-go="${e(target)}">${i('arrow',18)}${e(label)}</button>`;
const title=(h,p='')=>`<div class="screen-title"><h1 tabindex="-1">${e(h)}</h1>${p?`<p>${e(p)}</p>`:''}</div>`;
const empty=(h,p,button='看看已收錄地點',target='explore')=>`<div class="empty">${i('compass',35)}<h2>${e(h)}</h2><p>${e(p)}</p>${button?`<button class="btn outline" data-go="${target}">${e(button)}</button>`:''}</div>`;
const sources=ids=>`<details class="source-details"><summary>資料與照片來源</summary>${[...new Set(ids)].map(id=>{const s=SOURCES.find(s=>s.id===id);return s?`<div>${s.url?`<a href="${e(s.url)}" target="_blank" rel="noreferrer">${e(s.title)}</a>`:e(s.title)}<span>${e(s.publisher)}${s.checkedAt?'　核對 '+e(s.checkedAt):''}</span></div>`:''}).join('')}</details>`;
const sourceIds=p=>[...p.sourceIds,...p.id==='blueprint'?['photo-blueprint-day']:[]];
const navLink=(path,ic,label,active)=>`<a href="city.html#${path}" ${active===path?'aria-current="page"':''}>${i(ic,20)}<span>${label}</span></a>`;
function shell(html){const r=route(),s=store.getState();const active=['place','plan','guide','import','transport'].includes(r.name)?'explore':['friends','joint-plan','event','room','create'].includes(r.name)?'together':['memory','settings','notifications'].includes(r.name)?'me':r.name;return `<header class="top"><a class="brand" href="city.html#explore"><img src="assets/yoxi-logo.svg" alt="yoxi"><span>城市生活</span></a><nav class="main-nav" aria-label="主要功能">${navLink('explore','compass','探索',active)}${navLink('together','people','一起去',active)}<a href="index.html">${i('star',20)}<span>城市收藏</span></a>${navLink('me','book','我的',active)}</nav><div class="top-action"><button class="icon-btn" data-go="notifications" aria-label="通知">${i('bell',20)}</button><button class="ride" data-action="ride">${i('car',17)}<span>叫車</span></button></div></header>${s.activeProfileId!=='me'?`<div class="intro-banner"><span>測試人物：${e(person(s.activeProfileId))}</span><button data-action="switch-me">切回自己</button></div>`:''}<main class="page page-${e(r.name)}" id="content">${html}</main>`;}
function feature(p,reason){return `<article class="featured"><img class="cover" src="${e(p.image)}" alt="${e(p.name)}" fetchpriority="high"><div class="feature-top"><span>${i('pin',15)}${e(p.city)} ${e(p.area)}</span><button class="save-float ${saved(p.id)?'saved':''}" data-action="${store.getState().activeProfileId==='me'?'save':'switch-me'}" data-id="${p.id}" aria-label="${store.getState().activeProfileId!=='me'?'切回自己後收藏':saved(p.id)?'取消想去':'加入想去'}${e(p.name)}" aria-pressed="${saved(p.id)}">${i('heart',20)}</button></div><div class="feature-body"><div class="feature-facts"><span>${fee(p)}</span><span>${e(p.tags.slice(0,2).join('、'))}</span></div><h2>${e(p.name)}</h2><p>${e(reason||p.description)}</p>${p.confirmedMatches?.length?`<p>符合你在收藏記下的：${e(p.confirmedMatches.join('、'))}。</p>`:''}<button class="feature-open" data-go="place/${p.id}"><span>看看這個地方</span>${i('chevron',20)}</button></div></article>`;}
function smallPlace(p){return `<article class="place-small"><a class="thumb" href="#place/${p.id}"><img src="${e(p.image)}" alt="${e(p.name)}" loading="lazy"></a><div class="place-small-copy"><p class="place-area">${e(p.area)}</p><h3>${e(p.name)}</h3><p class="place-fee">${fee(p)}</p><a class="text-btn" href="#place/${p.id}">查看地點 ${i('chevron',16)}</a></div></article>`;}
function explore(){const s=store.getState();const places=rankExplorationPlaces(s,{query:searchResult?searchText:'',filter,candidatePlaceIds:searchResult?searchResult.placeIds:null});return `<section class="discovery-stage"><div class="discovery-intro"><button class="city-selector" data-action="city">${i('pin',16)}${e(s.profile.city)}${i('chevron',13)}</button>${title('今天，想做什麼？')}<form class="search" id="search-form" aria-busy="${searchBusy}">${i('search',20)}<input name="query" aria-label="想找的地方或體驗" placeholder="免費、室內的看展去處" value="${e(searchText)}" maxlength="500"><button type="submit" aria-label="搜尋" ${searchBusy?'disabled':''}>${i(searchBusy?'refresh':'chevron',21)}</button></form><div class="chips" aria-label="探索主題">${['全部','攝影','看展','地方故事'].map(f=>`<button class="chip ${filter===f||!filter&&f==='全部'?'active':''}" data-action="filter" data-value="${f==='全部'?'':f}" aria-pressed="${filter===f||!filter&&f==='全部'}">${f}</button>`).join('')}</div></div><div class="discovery-shortcuts"><button class="discovery-shortcut" data-go="import"><span class="shortcut-icon">${i('plus',20)}</span><span>貼上想去的地方</span>${i('chevron',16)}</button><button class="discovery-shortcut" data-go="friends"><span class="shortcut-icon">${i('people',20)}</span><span>和朋友一起找</span>${i('chevron',16)}</button></div><div class="discovery-result" aria-busy="${searchBusy}"><h2 class="sr-only">${searchText?'符合這次想法的去處':'在台南，找一點新鮮事'}</h2>${searchBusy?`<div class="loading-destination" role="status" aria-label="正在尋找符合的去處"><div>${i('compass',28)}<p>正在找符合條件的地方…</p><div class="loading-line"></div></div></div>`:places.length?feature(places[0],searchResult?.items?.find(x=>x.placeId===places[0].id)?.reason):empty('目前沒有符合的地方',searchResult?.summary||'試試調整條件，或回到已收錄的地點。','清除搜尋','explore')}</div></section>${places.length>1?`<section class="other-destinations"><div class="section-title"><h2>也可以去這裡</h2></div><div class="secondary-places">${places.slice(1,3).map(smallPlace).join('')}</div></section>`:''}<section class="section strip"><div><h3>想去的地方，有人一起更好</h3><p>看看正在找人的邀約，或先認識同好。</p></div><button class="btn outline" data-go="together">找人一起去 ${i('chevron',16)}</button></section><p class="source-footer">目前收錄台南三個地點。網頁搜尋依已收錄條件篩選，AI 操作請看 Demo 影片。${searchResult?.mode==='local_model'?'本次以 AI 語意檢索找出候選，再依這次條件與興趣排序。':''}<button class="text-btn" data-action="about-data">資料與實作</button></p>`;}
function place(id){const p=getPlace(id);if(!p||p.testData)return missing();return back('探索')+`<div class="split wide"><div class="detail-visual"><img src="${e(p.image)}" alt="${e(p.name)}"><p>來源照片，非即時現場影像</p></div><div class="detail-body"><p class="eyebrow">${e(p.city)} ${e(p.area)}</p><h1 tabindex="-1">${e(p.name)}</h1><p class="muted">${e(p.description)}</p><div class="compact-facts"><span>${i('wallet',16)} ${fee(p)}</span><span>${i('clock',16)} ${p.experiences.reduce((n,x)=>n+x.minutes,0)} 分鐘可做的事</span></div><div class="activities">${p.experiences.map(x=>`<div class="activity"><h3>${e(x.title)}</h3><p>${e(x.detail)}</p></div>`).join('')}</div><div class="button-row"><button class="btn primary" data-go="plan/${id}">安排現場時間</button><button class="btn outline" data-action="${store.getState().activeProfileId==='me'?'save':'switch-me'}" data-id="${id}">${i('heart',18)}${store.getState().activeProfileId!=='me'?'切回自己後收藏':saved(id)?'已收藏':'加入想去'}</button></div><div class="rule"></div><div class="fact-row">${i('clock',21)}<div><h3>開放時間</h3><p>${e(p.hours?.label||'依官方公告')}${p.hours?.note?'。'+e(p.hours.note):''}</p></div></div><div class="fact-row">${i('pin',21)}<div><h3>${e(p.address)}</h3><a class="text-btn" href="https://www.google.com/maps/search/?api=1&query=${encodeURIComponent(p.name+' '+p.address)}" target="_blank" rel="noreferrer">在地圖查看 ${i('external',14)}</a></div></div>${p.fees.map(f=>`<div class="fact-row">${i('wallet',21)}<div><h3>${e(f.label)} ${money(f.amount)}</h3>${f.note?`<p>${e(f.note)}</p>`:''}</div></div>`).join('')}<div class="button-row"><button class="btn outline" data-action="create-place" data-id="${id}">約人一起去</button><button class="btn outline" data-go="transport/${id}">交通方式</button></div>${id==='blueprint'?'<div class="section"><a class="strip inline-link" href="index.html">打開這個街角的城市收藏 '+i('chevron',18)+'</a></div>':''}${sources(sourceIds(p))}</div></div><div id="place-memories"></div>`;}
function importPage(){if(store.getState().activeProfileId!=='me')return title('自己的地點收藏')+b('切回自己','switch-me','primary');return `<div class="narrow">${back('探索')}${title('把想去的地方留下來')}<form id="import-form"><div class="form-row"><label for="import-text">貼文文字、地圖連結或地點名稱</label><textarea id="import-text" name="input" maxlength="5000" placeholder="想去藍晒圖文創園區拍照，也想看看臺南國家美術館。">${e(importText)}</textarea></div><button class="btn primary" type="submit">找出地點</button></form><button class="text-btn" data-action="import-example">使用雙地點範例</button>${importResult?`<section class="section"><h2>確認要留下的地方</h2>${importResult.candidates.length?`<form id="save-import">${importResult.candidates.map(c=>{const p=getPlace(c.placeId);return `<label class="candidate"><input name="placeIds" type="checkbox" value="${c.placeId}" checked><img src="${p.image}" alt=""><div><strong>${e(c.name)}</strong><span>${e(c.city)} ${e(p.area)}</span></div></label>`}).join('')}<div class="form-row section"><label for="import-interests">這批地點感興趣的事（稍後逐一確認）</label><input id="import-interests" name="interests" placeholder="例如：攝影、線條、看展"></div><button class="btn primary" type="submit">加入想去清單</button></form>`:empty('還沒找到地點','可以補上地點全名，或從下面選取。','','')}<div class="section">${!importResult.candidates.length?PLACES.filter(p=>!p.testData).map(p=>`<button class="list-row" data-action="import-pick" data-id="${p.id}"><img src="${p.image}" alt=""><span class="row-copy">${e(p.name)}</span>${i('plus',18)}</button>`).join(''):''}</div>${importResult.links.some(l=>l.status==='short_link_unresolved')?'<p class="small muted">短連結尚未展開，請補上地點名稱。</p>':''}</section>`:''}<details class="source-details"><summary>分享與辨識範圍</summary><p>目前可貼上文字與具名地圖連結，確認後才收藏。iOS 分享選單擴充、圖片辨識與影片尚未接入。</p></details></div>`;}
function planPage(id){const p=getPlace(id);if(!p||p.testData)return missing();const d=planDraft?.placeId===id?planDraft:{placeId:id,siteMinutes:60,budget:null,interests:['攝影'],participants:[],query:''};return back(p.name,'place/'+id)+`<div class="split"><div>${title('留一段時間，做想做的事',p.name)}<form id="plan-form" data-id="${id}"><input type="hidden" name="query" value="${e(d.query||'')}">${d.query?`<p class="small muted" style="margin-bottom:20px">本次條件：${e(d.query)}</p>`:''}<div class="form-grid"><div class="form-row"><label for="duration">現場時間</label><select id="duration" name="minutes">${[15,25,40,60,90,120].map(v=>`<option value="${v}" ${d.siteMinutes===v?'selected':''}>${v} 分鐘</option>`).join('')}</select></div><div class="form-row"><label for="budget">每人入場預算</label><input id="budget" name="budget" type="number" min="0" step="1" placeholder="不限" value="${d.budget??''}"></div></div><div class="form-row"><label for="plan-interests">我想做的事</label><input id="plan-interests" name="interests" value="${e(d.interests.join('、'))}"></div><div class="form-row"><label for="plan-friend">同行者想做的事（選填）</label><input id="plan-friend" name="friend" placeholder="例如：看展、地方故事" value="${e(d.participants.flatMap(x=>x.interests).join('、'))}"></div><button class="btn primary" type="submit">安排現場時間</button></form><p class="source-footer">安排單一地點內的體驗，往返時間與交通費另查。</p></div><div class="plan-output" aria-live="polite">${planError?`<p class="notice" role="alert">${e(planError)}</p>`:''}${planResult?.placeId===id?renderPlan(planResult):`<img src="${p.image}" alt="${e(p.name)}" style="width:100%;height:360px;object-fit:cover;border-radius:14px">`}</div></div>`;}
function steps(p){return `<ol class="timeline">${p.steps.map(x=>`<li><span class="time">${x.minutes}<br>分鐘</span><h3>${e(x.title)}</h3><p>${e(x.detail)}</p></li>`).join('')}</ol>`;}
function renderPlan(p){return `<h2>這次的 ${p.totalMinutes} 分鐘</h2>${steps(p)}<div class="plan-summary"><div><p>每人已知費用</p><strong>${money(p.knownCost)}</strong></div><p>${e(p.unknownCostItems.map(x=>x==='交通'?'交通另計':x+'待確認').join('、'))}</p></div><div class="button-row section"><button class="btn primary" data-action="save-plan">存入我的安排</button><button class="btn outline" data-action="plan-invite">約人一起去</button></div>`;}
function guidePage(id){const p=store.getState().plans.find(p=>p.id===id);if(!p)return missing();if(p.jointContext)return jointPlanPage(id);const place=getPlace(p.placeId);return `<div class="narrow">${back('我的安排','me')}${title(place.name)}${steps(p)}<div class="button-row"><button class="btn primary" data-go="memory/${p.placeId}">留下這次紀念</button><button class="btn outline" data-go="transport/${p.placeId}">交通方式</button></div><section id="place-guide" data-place-id="${p.placeId}"></section>${sources(sourceIds(place))}</div>`;}
function dinner(g){const members=g.membership.filter(m=>!['left','interested'].includes(m.status));return `<div class="dinner-photo"><img src="assets/banquet-reference.jpg" alt="台菜拼盤示意照片"><span class="photo-note">菜色示意，非本次菜單</span><div class="dinner-seats"><div class="seat-avatars">${members.map(m=>`<span class="avatar" title="${e(person(m.userId))}">${e(person(m.userId).slice(0,1))}</span>`).join('')}${members.length<g.maxPeople?`<span class="avatar vacant">${i('plus',18)}</span>`:''}</div><div><strong>${members.length} 人已加入</strong><p>${members.length<g.maxPeople?(g.maxPeople-members.length)+' 個位子可加入':'名額已滿'}</p></div></div></div>`;}
function together(){const s=store.getState();return `<div class="my-heading">${title('找人一起去')}<button class="text-btn" data-go="create">${i('plus',18)}發起邀約</button></div><div class="choice-tabs" role="group" aria-label="同行方式"><button data-action="together-tab" data-value="events" class="${togetherTab==='events'?'active':''}">看看邀約</button><button data-action="together-tab" data-value="people" class="${togetherTab==='people'?'active':''}">先找同好</button></div>${togetherTab==='people'?`<div class="people-grid">${TEST_PROFILES.filter(p=>p.id!=='me'&&!s.profile.blockedUserIds.includes(p.id)).map(p=>`<article class="person"><span class="avatar">${e(p.name.slice(0,1))}</span><h2>${e(p.name)}</h2><p>${e(p.interests.join('、'))}<br>${e(p.area)}</p><button class="text-btn" data-action="choose-person" data-id="${p.id}">一起找去處 ${i('chevron',15)}</button></article>`).join('')}</div><p class="source-footer">目前人物為本機測試資料，回覆由展示者切換身分操作。</p>`:s.invitations.filter(g=>!s.profile.blockedUserIds.includes(g.hostId)).map((raw,n)=>{const g=getInvitationView(s,raw.id),estimated=calculateGroupCosts(g,Array.from({length:g.maxPeople},(_,n)=>'p'+n));return `<article class="event-layout ${n?'section':''}">${g.placeId==='table-demo'?dinner(g):`<div class="detail-visual"><img style="height:400px" src="${getPlace(g.placeId).image}" alt="${e(getPlace(g.placeId).name)}"></div>`}<div class="event-copy"><span class="status ${g.status!=='ready'?'pending':''}">${e(invitationStatus(g))}</span><h2 style="margin-top:17px">${e(g.title)}</h2><p class="sub">${e(g.activity)}</p><div class="event-meta"><div>${i('calendar',18)}${dateText(g.startAt)}</div><div>${i('people',18)}${g.committedCount} 人已加入${g.remainingSeats?'，還有 '+g.remainingSeats+' 個位子':''}</div><div>${i('pin',18)}${e(getPlace(g.placeId).area)}${g.placeId==='table-demo'?'，餐廳待確認':''}</div></div><div class="cost-line"><span>${g.maxPeople} 人時，每人</span><div><strong>${costDisplay(estimated,'p0')}</strong></div></div><p class="small muted">${costExtra(estimated)}。費用為示範情境。</p><button class="btn primary full" style="margin-top:24px" data-go="event/${g.id}">查看時間與參加條件 ${i('chevron',17)}</button><p class="source-footer">本機示範邀約，尚未向店家訂位。</p>${g.placeId==='table-demo'?mealCredit():''}</div></article>`}).join('')}<section class="section strip"><div><h3>朋友有了，地點還沒決定？</h3><p>把彼此想做的事放在一起，找共同去處。</p></div><button class="btn outline" data-go="friends">一起挑地方 ${i('chevron',16)}</button></section>`;}
function mealCredit(){return '<details class="source-details"><summary>照片來源</summary><div><a href="https://commons.wikimedia.org/wiki/File:Taiwanese_cuisine.jpg" target="_blank" rel="noreferrer">台菜婚宴拼盤</a><span>WikiLaurent；Currentlybiscuit 調整亮度與銳利度。2007 年照片，依版面裁切。</span><a href="https://creativecommons.org/licenses/by-sa/3.0/" target="_blank" rel="noreferrer">CC BY-SA 3.0</a></div></details>';}
function costExtra(c){return c.unknownItems.map(x=>x==='交通'?'交通另計':x+'待確認').join('、')||'列入的費用已知';}
function eventPage(id){const s=store.getState(),g=getInvitationView(s,id);if(!g)return missing();const joined=g.myMembership&&!['left','interested'].includes(g.myMembership.status);const members=g.membership.filter(m=>!['left','interested'].includes(m.status)),ids=members.map(m=>m.userId);const canJoin=!joined&&g.remainingSeats>0&&['open','ready'].includes(g.status)&&Date.now()<Date.parse(g.deadlineAt);const costs=calculateGroupCosts(g,canJoin?[...ids,s.activeProfileId]:ids);return back('一起去','together')+`<div class="split"><div>${g.placeId==='table-demo'?dinner(g):`<div class="detail-visual"><img src="${getPlace(g.placeId).image}" alt="${e(getPlace(g.placeId).name)}"></div>`}<div class="members">${members.map(m=>`<div class="member"><span class="avatar">${e(person(m.userId).slice(0,1))}</span><div class="name">${e(person(m.userId))}<p>${m.userId===g.hostId?'主揪':''}</p></div><span class="state">${m.acceptedRevision===g.revision&&m.status==='confirmed'?'已確認目前安排':'待重新確認'}</span></div>`).join('')}</div></div><div>${title(g.title,g.activity)}<span class="status pending">${e(invitationStatus(g))}</span><div class="event-meta"><div>${i('calendar',20)}${dateText(g.startAt)}</div><div>${i('clock',20)}預計 ${Math.round((Date.parse(g.endAt)-Date.parse(g.startAt))/60000)} 分鐘</div><div>${i('people',20)}${g.minPeople} 人成團，最多 ${g.maxPeople} 人</div><div>${i('pin',20)}${e(getPlace(g.placeId).address||'台南中西區，餐廳待確認')}</div></div>${budgetBox(g,costs,canJoin?'你加入後的費用':'目前成員分攤費用',joined||canJoin?s.activeProfileId:ids[0])}${jointGroupReference(g)}<p class="small muted">${dateText(g.deadlineAt)} 截止。人數、時間或費用變動時，會通知所有成員重新確認。</p><div class="button-row section">${joined?b('進入同行房間','open-room','primary',`data-id="${id}"`):canJoin?b('確認條件並加入','join-review','primary',`data-id="${id}"`):`<button class="btn primary" disabled>${g.remainingSeats===0?'名額已滿':'目前無法加入'}</button>`}${!joined?b('先記為有興趣','interest','outline',`data-id="${id}"`):b('退出邀約','leave-review','outline',`data-id="${id}"`)}</div><p class="source-footer">本機示範邀約及費用。加入不會向店家訂位或扣款。</p>${g.placeId==='table-demo'?mealCredit():''}</div></div>`;}
function budgetBox(g,c,label,costUserId=store.getState().activeProfileId){return `<div class="budget-detail"><h3>${e(label)}</h3>${g.costItems.map(x=>`<div class="line"><span>${e(x.label)}${x.basis==='shared'?'（總額）':'（每人）'}</span><span>${money(x.amount)}</span></div>`).join('')}<div class="line"><span>參加人數</span><span>${c.count} 人</span></div><div class="line total"><span>每人已知費用</span><span>${costDisplay(c,costUserId)}</span></div><p>${costExtra(c)}。${c.agreementStatus==='agreed'?'所有成員已同意這份安排。':'目前為試算，需全員同意目前安排。'}</p></div>`;}
function manualFriends(){
 const matching=friendSearched&&!friendParseError?searchPlaces({city:store.getState().profile.city,mustInclude:[...friendMine,...friendWants]}).places.filter(p=>!p.testData):[];
 const acts=(p,t)=>p.experiences.filter(x=>x.tags.some(tag=>t.includes(tag))).map(x=>x.title).slice(0,2).join('、');
 return `<div class="friend-page"><form id="friend-form"><div class="form-grid"><div class="form-row"><label for="friend-mine">我想做什麼</label><input id="friend-mine" name="mine" value="${e(friendInput.mine)}" required></div><div class="form-row"><label for="friend-wants">${e(friendPerson?.name||'朋友')}想做什麼</label><input id="friend-wants" name="friend" value="${e(friendInput.friend)}" required></div></div><button class="btn primary" type="submit">找共同去處</button></form>${friendSearched?`<section id="friend-results" class="friend-results" aria-labelledby="friend-results-title"><h2 id="friend-results-title" tabindex="-1">${friendParseError?'調整想做的事':matching.length?`找到 ${matching.length} 個共同去處`:'目前沒有同時符合的地方'}</h2>${friendParseError?`<p class="notice" role="alert">${e(friendParseError)}</p>`:matching.length?matching.map(p=>`<article class="friend-result"><img src="${p.image}" alt="${e(p.name)}"><div class="friend-result-copy"><h3>${e(p.name)}</h3><p class="small muted">${fee(p)}，交通另計</p><div class="shared-reasons"><div><strong>你想要的</strong><p>${e(acts(p,friendMine))}</p></div><div><strong>${e(friendPerson?.name||'朋友')}想要的</strong><p>${e(acts(p,friendWants))}</p></div></div><button class="btn primary" data-action="friend-plan" data-id="${p.id}">把兩人的想法排進去</button></div></article>`).join(''):'<p class="muted">可以改一個條件，再一起挑。</p>'}</section>`:''}</div>`;
}

function friends(){return `<div class="friend-page">${back('一起去','together')}${title('和朋友一起找')}<div class="choice-tabs joint-entry-tabs" role="group" aria-label="一起找的方式"><button data-action="friends-mode" data-value="ai" class="${friendsMode==='ai'?'active':''}" aria-pressed="${friendsMode==='ai'}">AI 一起安排</button><button data-action="friends-mode" data-value="manual" class="${friendsMode==='manual'?'active':''}" aria-pressed="${friendsMode==='manual'}">自行選條件</button></div>${friendsMode==='ai'?'<div id="joint-root"></div>':manualFriends()}</div>`;}
function currentJoint(id=route().id){if(id){const plan=store.getState().plans.find(p=>p.id===id);return plan?.jointContext?{plan,planInput:plan.jointContext.planInput,jointContext:plan.jointContext,saved:true}:null;}return jointDraft?{...jointDraft,saved:false}:null;}
function jointPlanPage(id=route().id){const item=currentJoint(id);if(!item)return back('一起去','together')+empty('請先選擇共同安排','在「和朋友一起找」選好地點後，這裡會保留兩人的需要與安排。','和朋友一起找','friends');return back(item.saved?'我的安排':'返回共同安排',item.saved?'me':'friends')+renderJointConfirmation(item.plan,item.jointContext,{saved:item.saved,error:jointError})+(item.saved?`<div class="narrow section"><div class="button-row"><button class="btn primary" data-go="memory/${item.plan.placeId}">留下這次紀念</button><button class="btn outline" data-go="transport/${item.plan.placeId}">交通方式</button></div><section id="place-guide" data-place-id="${item.plan.placeId}"></section></div>`:'');}
function jointGroupReference(g){return g.sourceJointContext?`<details class="joint-planner jp-review-brief"><summary>最初的共同想法與安排依據</summary>${renderJointContext(g.sourceJointContext)}${renderJointLimitations(g.sourceJointContext)}</details>`:'';}
function currentJointInterests(){const refreshed=store.refresh();if(!refreshed.ok)throw new Error(refreshed.error.message);return getExplorationPreferences(store.getState()).interests;}
function mountJoint(){const container=$('#joint-root');if(!container)return;jointMount=mountJointPlanner(container,{showHeading:false,displayName:store.getState().profile.displayName,friendName:friendPerson?.name||'朋友',getProfileInterests:currentJointInterests,capabilities:caps.generative,sessionState:jointState,onStateChange:s=>{jointState=s;},onManual:()=>{friendsMode='manual';render();},selectLabel:'查看這次安排',onSelect:bundle=>{const checked=prepareJointHandoff(bundle,{displayNames:{me:store.getState().profile.displayName,friend:friendPerson?.name||'朋友'}});if(!checked.ok)throw new Error(checked.error.message);checked.value.jointContext.friendUserId=friendPerson?.id??null;jointDraft=checked.value;jointError='';go('joint-plan');}});}
function confirmationSummary(g,userId){
 const previous=g.history?.find(h=>h.revision===g.myMembership?.acceptedRevision);
 const old=previous?.arrangement;
 const calendarDay=new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Taipei',year:'numeric',month:'2-digit',day:'2-digit'});
 const timeRange=a=>dateText(a.startAt)+' – '+(calendarDay.format(new Date(a.startAt))===calendarDay.format(new Date(a.endAt))?new Date(a.endAt).toLocaleTimeString('zh-TW',{timeZone:'Asia/Taipei',hour:'2-digit',minute:'2-digit',hour12:false}):dateText(a.endAt));
 const total=c=>c.knownTotal===0&&c.unknownItems.some(x=>x!=='交通')?'待確認':money(c.knownTotal);
 const row=(label,value,before)=>`<div><dt>${label}</dt><dd>${before&&before!==value?`<span class="previous-value">原為 ${e(before)}</span>`:''}<strong>${e(value)}</strong></dd></div>`;
 return `<div class="notice arrangement-confirmation"><h3>安排有更新，請重新確認</h3><dl>${row('活動時間',timeRange(g),old?timeRange(old):null)}${row('目的地',getPlace(g.placeId).name,old?getPlace(old.placeId)?.name:null)}${row('目前人數',g.committedCount+' 人',previous?.costs?previous.costs.count+' 人':null)}${row('已知總額',total(g.costs),previous?.costs?total(previous.costs):null)}${row('每人已知費用',costDisplay(g.costs,userId),previous?.costs?costDisplay(previous.costs,userId):null)}</dl><p>${e(costExtra(g.costs))}。${g.confirmationDeadlineAt?'請在 '+dateText(g.confirmationDeadlineAt)+' 前確認。':''}</p><button class="btn primary" data-action="confirm-group" data-id="${e(g.id)}">同意目前安排</button></div>`;
}
function showFormError(form,error){
 form.querySelectorAll('[data-form-error]').forEach(n=>n.remove());
 form.querySelectorAll('[aria-invalid]').forEach(n=>{n.removeAttribute('aria-invalid');n.removeAttribute('aria-describedby')});
 let field=error.code==='schedule_conflict'||error.code==='time_invalid'?'start':error.code==='people_invalid'||error.code==='capacity_too_small'?'min':error.code==='cost_invalid'?'cost':error.code==='place_missing'?'placeId':error.details?.field||'title';
 const input=form.elements.namedItem(field)||form.querySelector('input');
 const box=document.createElement('div');box.className='form-error';box.dataset.formError='';box.id=form.id+'-error';box.setAttribute('role','alert');box.tabIndex=-1;
 const text=document.createElement('p');text.textContent=error.message;
 if(error.code==='schedule_conflict'){
  const conflict=getInvitationView(store.getState(),error.details?.invitationId);
  if(conflict)text.textContent=`這個時段和「${conflict.title}」重疊（${dateText(conflict.startAt)}）。請調整時間。`;
 }
 box.append(text);const row=input?.closest('.form-row');if(row)row.append(box);else form.prepend(box);
 input?.setAttribute('aria-invalid','true');input?.setAttribute('aria-describedby',box.id);input?.focus({preventScroll:true});box.scrollIntoView({block:'center',behavior:'instant'});
}

function room(id){const s=store.getState(),g=getInvitationView(s,id);if(!g)return missing();const m=g.myMembership,joined=m&&!['left','interested'].includes(m.status);if(!joined)return back('邀約','event/'+id)+empty('先查看參加條件','加入後才能在房間討論。','查看邀約','event/'+id);return back(g.title,'event/'+id)+`<div class="room"><div>${title('一起把安排定下來')}<span class="status ${g.status==='ready'?'':'pending'}">${e(invitationStatus(g))}</span>${m.status==='needs_reconfirmation'?confirmationSummary(g,s.activeProfileId):''}<div class="event-meta"><div>${i('calendar',18)}${dateText(g.startAt)}</div><div>${i('pin',18)}${e(getPlace(g.placeId).name)}</div></div>${budgetBox(g,g.costs,'目前安排')}${jointGroupReference(g)}<div class="members">${g.membership.filter(m=>!['left','interested'].includes(m.status)).map(m=>`<div class="member"><span class="avatar">${e(person(m.userId).slice(0,1))}</span><div class="name">${e(person(m.userId))}<p>${m.userId===g.hostId?'主揪':''}</p></div><span class="state">${m.status==='confirmed'&&m.acceptedRevision===g.revision?'已確認':'待重新確認'}</span></div>`).join('')}</div><div class="button-row"><button class="btn outline" data-go="transport/${g.placeId}">交通方式</button>${g.hostId===s.activeProfileId?b('修改安排','change-group','outline',`data-id="${id}"`):g.status==='needs_host'?b('我來接手主揪','claim-host','outline',`data-id="${id}"`):''}</div><button class="text-btn" data-action="leave-review" data-id="${id}">退出這次邀約</button></div><div><section class="room-chat"><h2>一起討論</h2><div class="messages">${getRoomMessages(s,id).map(msg=>msg.kind==='system'?`<p class="system-message">${e(msg.text)}</p>`:`<div class="room-message ${msg.authorId===s.activeProfileId?'self':''}"><div class="by">${e(person(msg.authorId))}　${new Date(msg.createdAt).toLocaleTimeString('zh-TW',{hour:'2-digit',minute:'2-digit'})}</div>${e(msg.text)}</div>`).join('')||'<p class="small muted">可以先聊想吃的菜或集合方式。</p>'}</div><form class="message-form" id="message-form" data-id="${id}"><input name="text" aria-label="留言" placeholder="留個訊息" maxlength="2000" required><button class="btn primary" type="submit" aria-label="傳送">${i('send',19)}</button></form></section><details class="demo-menu"><summary>本機測試人物與通知</summary><p>切換身分後，可由各成員確認、退出或接手。訊息只存在這個瀏覽器。</p><div class="button-row">${TEST_PROFILES.map(p=>b((p.id===s.activeProfileId?'目前：':'')+p.name,'switch-profile','outline',`data-id="${p.id}"`)).join('')}</div><button class="text-btn" data-go="notifications">查看目前人物的通知</button></details></div></div>`;}
function createPage(){let d=new Date();d.setDate(d.getDate()+7);d.setHours(14,0,0,0);const defaults=invitationPlanDefaults(createContext?.plan,{startAt:d.toISOString()}).value;const start=dateLocal(d),end=dateLocal(new Date(defaults.endAt)),deadline=dateLocal(new Date(+d-86400000));return `<div class="narrow">${back('一起去','together')}${title('把想做的事，約成一趟')}${createContext?.jointContext?`<details class="jp-review-brief joint-planner"><summary>這次的共同安排與待確認事項</summary>${renderJointContext(createContext.jointContext)}${renderJointLimitations(createContext.jointContext)}</details>`:''}<form id="create-form"><div class="form-row"><label for="event-title">邀約名稱</label><input id="event-title" name="title" maxlength="80" required value="${e(createContext?.placeId?'一起去'+getPlace(createContext.placeId).name:'')}" placeholder="週末一起拍城市線條"></div><div class="form-row"><label for="event-activity">想做的事與參加條件</label><textarea id="event-activity" name="activity" required maxlength="1000" placeholder="一起拍建築，手機或相機都可以。">${e(createContext?.plan?.steps.map(x=>x.title).join('、')||'')}</textarea></div><div class="form-row"><label for="event-place">目的地</label><select id="event-place" name="placeId">${PLACES.map(p=>`<option value="${p.id}" ${createContext?.placeId===p.id?'selected':''}>${e(p.name)}</option>`).join('')}</select></div><div class="rule"></div><div class="form-grid"><div class="form-row"><label for="event-start">開始時間</label><input id="event-start" name="start" type="datetime-local" value="${start}" required></div><div class="form-row"><label for="event-end">結束時間</label><input id="event-end" name="end" type="datetime-local" value="${end}" required></div></div><div class="form-row"><label for="event-deadline">報名截止</label><input id="event-deadline" name="deadline" type="datetime-local" value="${deadline}" required></div><div class="form-grid"><div class="form-row"><label for="event-min">幾人成團</label><input id="event-min" name="min" type="number" min="1" max="12" value="2" required></div><div class="form-row"><label for="event-max">最多人數</label><input id="event-max" name="max" type="number" min="1" max="12" value="4" required></div></div><div class="rule"></div><div class="form-grid"><div class="form-row"><label for="event-cost-label">費用項目</label><input id="event-cost-label" name="costLabel" value="${e(defaults.costLabel)}" required></div><div class="form-row"><label for="event-cost">金額（NT$）</label><input id="event-cost" name="cost" type="number" min="0" step="1" value="${createContext?.plan?.knownCost??''}" placeholder="未知留空"></div></div><div class="form-row"><label for="event-basis">怎麼計算</label><select id="event-basis" name="basis"><option value="shared">總額由參加的人分攤</option><option value="per_person" ${createContext?.plan?'selected':''}>每人各自支付這個金額</option></select></div>${defaults.unknownCostItems.length?`<p class="small muted">${e(defaults.unknownCostItems.join('、'))}的費用待確認，會一併保留。</p>`:''}${createContext?.people?.length?`<p style="margin:15px 0">一併邀請：${e(createContext.people.map(p=>p.name).join('、'))}</p>`:''}<button type="submit" class="btn primary full">建立邀約</button><p class="source-footer">邀約只建立在本機展示，不會公開招募或向店家訂位。</p></form></div>`;}
function me(){const s=store.getState();if(s.activeProfileId!=='me')return title('測試人物')+`<button class="btn primary" data-action="switch-me">切回自己的紀錄</button>`;const places=getSavedPlaces(s),plans=getMyPlans(s);return `<div class="my-heading">${title('我的城市生活')}<div class="button-row"><button class="text-btn" data-go="notifications">${i('bell',18)}通知</button><button class="text-btn" data-go="settings">${i('settings',18)}偏好與隱私</button></div></div><div class="choice-tabs"><button data-action="my-tab" data-value="saved" class="${myTab==='saved'?'active':''}">地點收藏</button><button data-action="my-tab" data-value="plans" class="${myTab==='plans'?'active':''}">我的安排</button><button data-action="my-tab" data-value="memories" class="${myTab==='memories'?'active':''}">旅行紀念</button></div>${myTab==='saved'?places.length?`<div class="saved-grid">${places.map(p=>`<article><a href="#place/${p.placeId}"><img src="${p.image}" alt="${e(p.name)}"></a><h3>${e(p.name)}</h3>${p.sourceInputs?.includes(INSPIRATION_SOURCE)?'<p class="small muted">來自「藍色街角」收藏場景</p>':''}<label class="sr-only" for="intent-${p.placeId}">想去狀態</label><select id="intent-${p.placeId}" data-intent="${p.placeId}">${[['want','想去'],['considering','還在考慮'],['planned','已安排'],['visited','已到訪（自行記錄）']].map(([v,t])=>`<option value="${v}" ${p.intent===v?'selected':''}>${t}</option>`).join('')}</select>${getConfirmedPlaceTerms(p).length?`<p class="small muted">想做的事：${e(getConfirmedPlaceTerms(p).join('、'))}</p>`:''}<button class="text-btn" data-action="collection-preferences" data-id="${p.placeId}">${getConfirmedPlaceTerms(p).length?'修改想做的事':'記下想做的事'}</button><div class="button-row"><button class="text-btn" data-go="plan/${p.placeId}">安排一趟</button><button class="text-btn" data-action="place-invitations" data-id="${p.placeId}">查看邀約</button></div></article>`).join('')}</div>`:empty('先留下想去的地方','找到喜歡的地點，按「加入想去」就會保存在這裡。'):myTab==='plans'?plans.length?plans.map(p=>`<div class="list-row"><img src="${getPlace(p.placeId).image}" alt=""><div class="row-copy"><h3>${e(getPlace(p.placeId).name)}</h3><p>${p.totalMinutes} 分鐘現場安排　${p.status==='completed'?'已完成':p.status==='cancelled'?'已取消':'已保存'}</p><button class="text-btn" data-go="guide/${p.id}">打開安排 ${i('chevron',15)}</button></div></div>`).join(''):empty('還沒有安排','選定地點後，可以把想做的事排進現場時間。'):'<div id="my-memories"></div>'}<section class="section strip"><div><h3>城市收藏冊</h3><p>打開旅伴與城市場景，看看自己留下的紀念卡。</p></div><a class="btn outline" href="index.html#album">打開收藏冊 ${i('chevron',16)}</a></section>`;}
function editCollectionPreferences(id){
 const s=store.getState(),c=s.collections.find(x=>x.placeId===id),p=getPlace(id);
 if(s.activeProfileId!=='me'||!c||!p||p.testData){toast('請切回自己，從地點收藏記下想做的事。');return;}
 const terms=getConfirmedPlaceTerms(c),choices=p.tags,other=terms.filter(x=>!choices.includes(x));
 modal('在'+p.name+'，想做什麼？',`<form id="collection-preferences-form" data-id="${e(id)}" data-collection-id="${e(c.id)}" data-revision="${c.confirmedPreferences?.revision||0}"><fieldset style="border:0;padding:0;margin:0 0 20px"><legend class="form-label">選擇吸引你的主題</legend><div class="chips">${choices.map(tag=>`<label class="chip"><input type="checkbox" name="terms" value="${e(tag)}" ${terms.includes(tag)?'checked':''}><span>${e(tag)}</span></label>`).join('')}</div></fieldset><div class="form-row"><label for="preference-other">其他想做的事（選填）</label><input id="preference-other" name="other" value="${e(other.join('、'))}" maxlength="409" placeholder="用頓號分開，每項最多 40 字"><p class="small muted">最多記下 10 項。探索會參考已收錄的相同主題，其他文字保存在這個地點。</p></div><p class="small muted">${s.profile.consents.useCollections?'目前會用這些內容協助探索推薦。':'探索推薦目前未使用收藏偏好。'}可在「偏好與隱私」調整。全部取消並清空文字，可移除這份記錄。</p><button class="btn primary full" type="submit" style="margin-top:20px">保存想做的事</button></form>`);
}
function memoryPage(id){const p=getPlace(id);if(!p||p.testData)return missing();const m=store.getState().memories.find(m=>m.placeId===id);return `<div class="narrow">${back('我的旅行紀念','me')}${title(p.name,'留下你拍的照片，或想記得的一句話。')}<div class="image-gallery" id="memory-gallery"></div><form id="memory-form" data-id="${id}"><div class="form-row"><label for="memory-photo">加入照片</label><input id="memory-photo" name="photo" type="file" accept="image/jpeg,image/png,image/webp"><p class="small muted">JPG、PNG、WebP，單張最多 8 MB。</p></div><div class="form-row"><label for="memory-note">想記住什麼（選填）</label><textarea id="memory-note" name="note" maxlength="3000" placeholder="那天最喜歡哪個片刻？">${e(m?.note||'')}</textarea></div><label class="check-line"><input type="checkbox" name="visited" ${m?.selfReportedVisitAt?'checked':''}><span>我有親自到訪（自行記錄）</span></label><button class="btn primary" type="submit">保存紀念</button></form>${m?b('刪除這份紀念','delete-memory','outline',`data-id="${m.id}" style="margin-top:20px"`):''}${id==='blueprint'?'<section class="section strip"><div><h3>把這個街角帶回來</h3><p>替旅伴選個角度，拍成自己的城市紀念卡。</p></div><a class="btn outline" href="index.html">打開城市收藏</a></section>':''}</div>`;}
function transport(id){const r=prepareHandoff({placeId:id});return `<div class="narrow">${back(id==='table-demo'?'一起去':'返回地點',id==='table-demo'?'together':'place/'+id)}${title('選好去處，再安排交通')}${r.ok?`<div class="transport-card"><h2>${e(r.value.destination)}</h2><p>${e(r.value.address)}</p></div><p>先複製目的地，再到 yoxi 確認上車位置、車資與叫車。</p><div class="button-row section">${b('複製目的地','copy-destination','outline',`data-id="${id}"`)}<a class="btn primary" href="https://yoxi.go.link/aG0qg" target="_blank" rel="noreferrer">開啟 yoxi ${i('external',17)}</a></div><p class="source-footer">目的地不會自動帶入官方 App。一起參加活動，也可以各自前往。</p>`:empty('集合地點還沒確定','確認餐廳與地址後，再選擇交通。','回到邀約','together')}</div>`;}
function settings(){if(store.getState().activeProfileId!=='me')return title('自己的偏好')+b('切回自己','switch-me','primary');const p=store.getState().profile;return `<div class="narrow">${back('我的','me')}${title('偏好與隱私')}<form id="settings-form" data-snapshot="${e(profileSettingsSnapshot(p))}"><div class="form-row"><label for="profile-name">顯示名稱</label><input id="profile-name" name="name" maxlength="40" value="${e(p.displayName)}"></div><div class="form-row"><label for="profile-interests">喜歡的事</label><input id="profile-interests" name="interests" value="${e(p.interests.join('、'))}"><p class="small muted">${p.interests.length&&!getConfirmedProfileInterests(p).length?'先前留下的興趣尚待本人確認。確認欄位後儲存，才會用來推薦。':'儲存後，探索會參考你在這裡確認的興趣。'}</p></div>${[['useCollections','用我在收藏記下的事協助探索推薦'],['invitationNotifications','接收邀約與安排變更通知'],['nearbyNotifications','接收附近收藏地點提醒'],['publicInterests','讓其他人看見我的興趣'],['publicArea','公開大致活動區域']].map(([key,label])=>`<label class="check-line"><input type="checkbox" name="${key}" ${p.consents[key]?'checked':''}><span>${label}</span></label>`).join('')}<p class="small muted">目前保存在這個瀏覽器，未接定位、推播或公開帳號服務。</p><button class="btn primary section" type="submit">儲存偏好</button><button class="text-btn" type="button" data-go="settings">重新讀取設定</button></form></div>`;}
function notifications(){const ns=getNotifications(store.getState());return `<div class="narrow">${back('我的','me')}${title('通知')}${ns.length?ns.slice().reverse().map(n=>`<div class="list-row"><div class="row-copy"><h3>${e(n.type==='group_invite'?'有人邀你一起去':'安排有更新')}</h3><p>${e(n.text)}</p>${n.invitationId?`<button class="text-btn" data-action="open-notification" data-id="${n.id}">查看邀約 ${i('chevron',15)}</button>`:''}</div></div>`).join(''):empty('目前沒有新通知','','','')}</div>`;}
function missing(){return empty('找不到這筆內容','回到探索，重新選擇想看的地方。');}
let photoUrls=[];function releasePhotoUrls(){photoUrls.forEach(url=>URL.revokeObjectURL(url));photoUrls=[];}async function renderPhotos(id){releasePhotoUrls();const m=store.getState().memories.find(m=>m.placeId===id),area=$('#memory-gallery');if(!m||!area)return;for(const key of m.photoBlobIds||[]){const p=await getPhoto(key);if(!p?.blob||!area.isConnected)continue;const img=document.createElement('img');img.src=URL.createObjectURL(p.blob);photoUrls.push(img.src);img.alt='我保存的照片';area.append(img)}}
function render(){if(guideMount){guideStates.set(guideKey,guideMount.getState());guideMount.dispose();guideMount=null;}if(jointMount){jointState=jointMount.getState();jointMount.dispose();jointMount=null;}memoryGallery?.dispose();memoryGallery=null;releasePhotoUrls();const r=route();const pages={explore,place:()=>place(r.id),import:importPage,plan:()=>planPage(r.id),guide:()=>guidePage(r.id),together,event:()=>eventPage(r.id),room:()=>room(r.id),friends,'joint-plan':()=>jointPlanPage(r.id),create:createPage,me,memory:()=>memoryPage(r.id),transport:()=>transport(r.id),settings,notifications};$('#app').innerHTML=shell((pages[r.name]||missing)());if(r.name==='friends'&&friendsMode==='ai')mountJoint();const guideNode=$('#place-guide');if(guideNode){guideKey=guideNode.dataset.placeId;guideMount=mountGuide(guideNode,{placeId:guideKey,sessionState:guideStates.get(guideKey),capabilities:caps.generative,onStateChange:value=>guideStates.set(guideKey,value)});}if(r.name==='memory')renderPhotos(r.id);const galleryNode=$('#place-memories')||$('#my-memories');if(galleryNode)memoryGallery=mountCityMemoryGallery(galleryNode,{cityStore:store,...(r.name==='place'?{placeId:r.id,title:'我的紀念',hideEmpty:true}:{title:'旅行紀念',showHeading:false})});}
function close(){if($('#modal').open)$('#modal').close()}
function joinReview(id){const g=getInvitationView(store.getState(),id);const members=g.membership.filter(m=>!['left','interested'].includes(m.status)).map(m=>m.userId);const c=calculateGroupCosts(g,[...members,store.getState().activeProfileId]);modal('確認加入這次邀約',`<h3>${e(g.title)}</h3><p>${dateText(g.startAt)}</p>${budgetBox(g,c,'加入後的安排')}<p>人數、時間或費用改變時，會請大家重新確認。</p>${b('確認加入','join','primary full',`data-id="${id}" data-revision="${g.revision}"`)}`)}
function changeGroup(id){const g=getInvitationView(store.getState(),id);modal('修改安排',`<form id="change-form" data-id="${id}" data-revision="${g.revision}"><div class="form-row"><label for="change-start">開始時間</label><input id="change-start" name="start" type="datetime-local" value="${dateLocal(new Date(g.startAt))}" required></div><div class="form-row"><label for="change-end">結束時間</label><input id="change-end" name="end" type="datetime-local" value="${dateLocal(new Date(g.endAt))}" required></div><div class="form-row"><label for="change-deadline">報名截止</label><input id="change-deadline" name="deadline" type="datetime-local" value="${dateLocal(new Date(g.deadlineAt))}" required></div>${g.costItems.map((x,n)=>`<div class="form-row"><label for="change-cost-${n}">${e(x.label)}（${x.basis==='shared'?'總額':'每人'}）</label><input id="change-cost-${n}" name="cost-${n}" type="number" min="0" step="1" value="${x.amount??''}" placeholder="未知留空"></div>`).join('')}<button class="btn primary full" type="submit">更新並通知成員</button></form>`)}
async function actions(t){const {action:a,id,value:v}=t.dataset;switch(a){
case 'close-modal':close();return;
case 'friends-mode':friendsMode=v;render();return;
case 'save-joint-plan':{const item=currentJoint();if(!item)return;const r=store.dispatch({type:'plan.save',plan:item.planInput,jointContext:item.jointContext});if(!r.ok){jointError=r.error.message;render();$('.jp-error')?.scrollIntoView({block:'center'});return;}jointError='';myTab='plans';toast('已存入我的安排');go('joint-plan/'+r.value.id);return;}
case 'invite-joint-plan':{const item=currentJoint();if(!item)return;const checked=buildSitePlan(item.planInput);if(!checked.ok||!plansAgree(checked.value,item.plan)){jointError=checked.error?.message||'地點資料或安排已變動，請回去重新安排。';render();return;}createContext={placeId:item.plan.placeId,plan:item.plan,jointContext:item.jointContext,people:TEST_PROFILES.filter(p=>p.id===item.jointContext.friendUserId)};go('create');return;}
case 'adjust-joint-plan':{const item=currentJoint();if(!item)return;jointState=restoreJointSession(item.jointContext);friendPerson=TEST_PROFILES.find(p=>p.id===item.jointContext.friendUserId)||null;friendsMode='ai';jointError='';go('friends');return;}

case 'save':if(act(saved(id)?'collection.remove':'collection.save',saved(id)?{placeId:id}:{placeIds:[id]}).ok){toast(saved(id)?'已加入想去清單':'已移出地點收藏');render()}return;
case 'collection-preferences':editCollectionPreferences(id);return;
case 'filter':filter=v;render();return;
case 'city':modal('選擇城市','<p>目前台南有三個已整理的地點。其他城市尚未收錄。</p><button class="btn primary full" data-action="close-modal">繼續看台南</button>');return;
case 'ride':modal('開啟 yoxi 叫車','<p>在官方 App 確認上車位置、目的地與車資。</p><a class="btn primary full" href="https://yoxi.go.link/aG0qg" target="_blank" rel="noreferrer">開啟 yoxi</a>');return;
case 'about-data':modal('資料與實作',`<p>此網頁以已收錄的條件篩選地點，提供手動規劃與收藏遊戲，未連接 AI。Demo 影片展示本機 multilingual-e5-small 的語意搜尋，以及 Qwen3.5-4B 的共同安排與地方問答。時間與費用來自已整理的資料。</p><p>目前收錄台南三個地點；未接即時活動、訂位與營業狀態。</p><p>人物、合菜邀約和費用為示範資料。網站沒有真實訂位、叫車或帳號同步。</p>${sources(SOURCES.map(x=>x.id))}`);return;
case 'import-example':importText='想去藍晒圖文創園區拍照，也想看看臺南國家美術館。';importResult=parsePlaceInput(importText);render();return;
case 'import-pick':importResult={candidates:[{placeId:id,name:getPlace(id).name,city:getPlace(id).city}],links:[]};render();return;
case 'save-plan':if(planResult){const r=act('plan.save',{plan:planDraft});if(r.ok){toast('已存入我的安排');myTab='plans';go('me')}}return;
case 'plan-invite':if(planResult){createContext={placeId:planResult.placeId,plan:planResult,people:friendPerson?[friendPerson]:[]};go('create')}return;
case 'create-place':createContext={placeId:id};go('create');return;
case 'together-tab':togetherTab=v;render();return;
case 'my-tab':myTab=v;render();return;
case 'choose-person':jointState=null;jointDraft=null;friendsMode='ai';friendPerson=TEST_PROFILES.find(p=>p.id===id);friendWants=[...friendPerson.interests];friendInput.friend=friendWants.join('、');friendParseError='';friendSearched=false;go('friends');return;
case 'friend-plan':planDraft={placeId:id,sourceKey:'friends/'+id,query:'',siteMinutes:90,budget:null,interests:friendMine,mustInclude:[...new Set([...friendMine,...friendWants])],participants:[{id:friendPerson?.id||'friend',interests:friendWants}]};planResult=null;planError='';go('plan/'+id);return;
case 'open-room':go('room/'+id);return;
case 'join-review':joinReview(id);return;
case 'join':if(act('group.join',{invitationId:id,revision:Number(t.dataset.revision)}).ok){close();toast('已加入，其他成員會收到安排更新');go('room/'+id)}return;
case 'interest':if(act('group.interest',{invitationId:id}).ok)toast('已記為有興趣，尚未加入');return;
case 'confirm-group':{const g=getInvitationView(store.getState(),id);if(act('group.confirm',{invitationId:id,revision:g.revision}).ok){toast('已同意目前安排');render()}return;}
case 'change-group':changeGroup(id);return;
case 'claim-host':if(act('group.claimHost',{invitationId:id}).ok)render();return;
case 'leave-review':modal('退出這次邀約',`<p>其他成員會收到人數與費用更新，再決定是否參加。</p>${b('確認退出','leave','danger full',`data-id="${id}"`)}`);return;
case 'leave':if(act('group.leave',{invitationId:id}).ok){close();go('event/'+id);toast('已退出邀約')}return;
case 'switch-profile':if(act('profile.switch',{userId:id}).ok){render();toast('已切換為'+person(id))}return;
case 'switch-me':if(act('profile.switch',{userId:'me'}).ok)render();return;
case 'copy-destination':{const r=await copyDestination({placeId:id});toast(r.ok?'目的地已複製':r.error.message);return;}
case 'place-invitations':{const gs=store.getState().invitations.filter(g=>g.placeId===id);modal(getPlace(id).name+'的邀約',gs.length?gs.map(g=>`<button class="list-row" data-go="event/${g.id}"><span class="row-copy"><h3>${e(g.title)}</h3><p>${dateText(g.startAt)}</p></span>${i('chevron',18)}</button>`).join(''):`<p>目前沒有這個地點的邀約。</p>${b('發起一起去的邀約','create-place','primary full',`data-id="${id}"`)}`);return;}
case 'open-notification':{const n=getNotifications(store.getState()).find(n=>n.id===id);if(n){act('notification.read',{notificationId:id});go('event/'+n.invitationId)}return;}
case 'delete-memory':modal('刪除這份紀念',`<p>會刪除這份文字與加入的照片。</p>${b('確認刪除','delete-memory-confirm','danger full',`data-id="${id}"`)}`);return;
case 'delete-memory-confirm':{const m=store.getState().memories.find(m=>m.id===id);if(act('memory.remove',{memoryId:id}).ok){for(const key of m?.photoBlobIds||[])await removePhoto(key);close();myTab='memories';go('me');toast('已刪除紀念')}return;}
}}
document.addEventListener('click',async ev=>{const t=ev.target.closest('[data-action],[data-go]');if(!t)return;ev.preventDefault();if(t.dataset.go){close();if(t.dataset.go==='create')createContext=null;if(t.dataset.go.startsWith('plan/')){const placeId=t.dataset.go.slice(5),fromSearch=route().name==='place'&&searchResult?.placeIds?.includes(placeId);startPlan(placeId,{query:fromSearch?searchText:'',sourceKey:fromSearch?'search/'+querySequence+'/'+placeId:'direct/'+placeId});}if(t.dataset.go==='explore'&&searchResult?.placeIds?.length===0){searchText='';searchResult=null;filter=''}go(t.dataset.go);return}try{await actions(t)}catch(err){console.error(err);toast(err.message||'操作未完成，請重試。')}});
document.addEventListener('submit',async ev=>{const f=ev.target;if(!f.id)return;ev.preventDefault();const fd=new FormData(f),v=k=>String(fd.get(k)||'');const submit=f.querySelector('[type=submit]');try{switch(f.id){
case 'collection-preferences-form':{const parsed=parsePreferenceTerms(fd.getAll('terms'),v('other'));if(!parsed.ok){showFormError(f,parsed.error);return;}const r=store.dispatch({type:'collection.preferences',placeId:f.dataset.id,terms:parsed.value,expectedCollectionId:f.dataset.collectionId,expectedRevision:Number(f.dataset.revision)});if(!r.ok){showFormError(f,r.error);return;}close();render();$('[data-action="collection-preferences"][data-id="'+f.dataset.id+'"]')?.focus();toast(parsed.value.length?'想做的事已保存':'已清除這份想做的事');return;}
case 'search-form':{searchText=v('query').trim();filter='';searchResult=null;const seq=++querySequence;if(!searchText){render();return}searchBusy=true;render();const res=await ai.recommend({query:searchText,city:store.getState().profile.city});if(seq!==querySequence)return;searchBusy=false;if(res.ok)searchResult=res.value;else{searchResult={placeIds:[],summary:res.error.message};toast(res.error.message)}if(route().name==='explore')render();return;}
case 'import-form':importText=v('input').trim();importResult=parsePlaceInput(importText);render();return;
case 'save-import':if(act('collection.save',{placeIds:fd.getAll('placeIds'),interests:splitTerms(v('interests')),sourceInput:importText}).ok){toast('地點已保存，可逐一記下想做的事');myTab='saved';go('me')}return;
case 'plan-form':{planDraft={placeId:f.dataset.id,sourceKey:planDraft?.sourceKey||'direct/'+f.dataset.id,query:v('query'),siteMinutes:Number(v('minutes')),budget:v('budget')===''?null:Number(v('budget')),interests:splitTerms(v('interests')),participants:v('friend').trim()?[{id:friendPerson?.id||'friend',interests:splitTerms(v('friend'))}]:[]};planError='';const r=buildSitePlan(planDraft);if(r.ok){planResult=r.value;render();$('.timeline')?.scrollIntoView({block:'center',behavior:'smooth'})}else{planResult=null;planError=r.error.message+(r.error.details?.requiredMinutes?' 需要 '+r.error.details.requiredMinutes+' 分鐘。':'');render();$('.plan-output')?.scrollIntoView({block:'nearest',behavior:'smooth'})}return;}
case 'friend-form':{friendInput={mine:v('mine'),friend:v('friend')};const mine=readInterests(friendInput.mine),friend=readInterests(friendInput.friend);friendMine=mine.tags;friendWants=friend.tags;const unknown=[...mine.unknown,...friend.unknown];friendParseError=unknown.length?'目前還無法辨認「'+unknown.join('、')+'」。可以填攝影、看展、文學或地方故事。':!friendMine.length||!friendWants.length?'請填入兩人各自想做的事。':'';friendSearched=true;render();requestAnimationFrame(()=>{const h=$('#friend-results-title');h?.focus({preventScroll:true});h?.scrollIntoView({block:'start',behavior:matchMedia('(prefers-reduced-motion:reduce)').matches?'instant':'smooth'});});return;}
case 'create-form':{if(createContext?.plan&&v('placeId')!==createContext.plan.placeId){showFormError(f,{code:'place_changed',message:'目的地已更改，請先回到地點重新安排。',details:{field:'placeId'}});return;}const invitation={title:v('title'),activity:v('activity'),placeId:v('placeId'),startAt:new Date(v('start')).toISOString(),endAt:new Date(v('end')).toISOString(),deadlineAt:new Date(v('deadline')).toISOString(),minPeople:Number(v('min')),maxPeople:Number(v('max')),costItems:[{id:'activity',label:v('costLabel'),amount:v('cost')===''?null:Number(v('cost')),basis:v('basis'),status:createContext?.plan&&v('cost')!==''&&Number(v('cost'))===createContext.plan.knownCost&&v('costLabel')==='已知入場費用'&&v('basis')==='per_person'?'catalog':'user_entered'},...(createContext?.plan?.unknownCostItems??[]).filter(x=>x!=='交通').map((label,n)=>({id:'unknown-'+n,label,amount:null,basis:'per_person',status:'unknown'}))],description:jointInviteDescription(createContext?.jointContext),...(createContext?.jointContext?{sourceJointContext:createContext.jointContext}:{})};const r=store.dispatch({type:'group.create',invitation});if(!r.ok){showFormError(f,r.error);return;}if(r.ok){if(createContext?.people?.length)act('group.invite',{invitationId:r.value.id,userIds:createContext.people.map(p=>p.id)});createContext=null;toast('邀約已建立');go('room/'+r.value.id)}return;}
case 'message-form':if(act('message.send',{invitationId:f.dataset.id,text:v('text')}).ok){render();$('.messages')?.scrollTo({top:$('.messages').scrollHeight});$('#message-form input')?.focus()}return;
case 'change-form':{const g=getInvitationView(store.getState(),f.dataset.id);const r=store.dispatch({type:'group.change',invitationId:g.id,revision:Number(f.dataset.revision),changes:{startAt:new Date(v('start')).toISOString(),endAt:new Date(v('end')).toISOString(),deadlineAt:new Date(v('deadline')).toISOString(),costItems:g.costItems.map((x,n)=>({...x,amount:v('cost-'+n)===''?null:Number(v('cost-'+n))}))}});if(r.ok){close();render();toast('已更新，等待成員重新確認')}else showFormError(f,r.error);return;}
case 'settings-form':{const r=store.dispatch({type:'settings.update',expectedSnapshot:f.dataset.snapshot,displayName:v('name'),interests:splitTerms(v('interests')),consents:Object.fromEntries(['useCollections','invitationNotifications','nearbyNotifications','publicInterests','publicArea'].map(k=>[k,fd.has(k)]))});if(!r.ok){showFormError(f,r.error);return;}f.dataset.snapshot=profileSettingsSnapshot(store.getState().profile);render();$('#profile-interests')?.focus();toast('偏好已保存');return;}
case 'memory-form':{const old=store.getState().memories.find(m=>m.placeId===f.dataset.id),file=fd.get('photo');let key=null;submit.disabled=true;try{if(file?.size)key=await savePhoto(file);const r=act('memory.save',{placeId:f.dataset.id,note:v('note'),photoBlobIds:[...(old?.photoBlobIds||[]),...key?[key]:[]],selfReportedVisitAt:fd.has('visited')?old?.selfReportedVisitAt||new Date().toISOString():null});if(r.ok){toast('紀念已保存');render()}else if(key)await removePhoto(key)}finally{submit.disabled=false}return;}

}}catch(err){console.error(err);toast(err.message||'操作未完成，請檢查輸入。');if(submit)submit.disabled=false}});
document.addEventListener('input',ev=>{if(ev.target.closest('#plan-form')&&planResult){planResult=null;planError='條件已更改，請重新安排。';const output=$('.plan-output');if(output)output.innerHTML='<p class="notice" role="status">'+e(planError)+'</p>';}});
document.addEventListener('change',ev=>{if(ev.target.matches('[data-intent]'))act('collection.intent',{placeId:ev.target.dataset.intent,intent:ev.target.value})});
window.addEventListener('hashchange',()=>{close();render();window.scrollTo(0,0);$('h1')?.focus({preventScroll:true})});
window.addEventListener('storage',ev=>{if(ev.key!=='yoxi-city-life-polished-v1')return;const r=store.refresh();if(r.ok&&r.value&&!document.activeElement?.closest('form')&&!$('#modal').open)render();});
render();ai.getCapabilities().then(c=>{caps=c;jointMount?.setCapabilities(c.generative??{status:'unavailable'});guideMount?.setCapabilities(c.generative??{status:'unavailable'});});
act('group.expire');
roomTimer=setInterval(()=>{const before=JSON.stringify(store.getState().invitations);const r=act('group.expire');if(r.ok&&before!==JSON.stringify(store.getState().invitations)&&['together','room','event'].includes(route().name))render()},30000);
window.__city={store,ai,get route(){return route()},go};
